// R44 real production-owner verification; private same-process pipes only.
#include "input_host_pipe_transport.h"
#include "json.hpp"
#include <iostream>
#include <stdexcept>
#include <thread>
#include <algorithm>
#include <exception>
using json=nlohmann::json;
namespace transport=ymcc::inputHost::pipeTransport;
static unsigned checks=0,pairs=0;
static json cases=json::array();
static void check(bool b,const char* why){++checks;if(!b)throw std::runtime_error(std::string(why)+" error="+std::to_string(GetLastError()));}
static json result(const transport::Result& r){return {{"ok",r.ok},{"error",r.error},{"bytes",r.byteCountKnown?json(r.transferred):json(nullptr)},{"admitted",r.admitted},{"terminal",r.terminal},{"retired",r.retired},{"apiReturnedTrue",r.apiReturnedTrue},{"initialError",r.initialError},{"queryAttempted",r.queryAttempted},{"queryReturnedTrue",r.queryReturnedTrue},{"queryError",r.queryError},{"cancelAttempted",r.cancelAttempted},{"cancelError",r.cancelError},{"operation",r.operation},{"lease",r.lease}};}
static json snapshot(transport::Runtime& owner){auto s=owner.snapshot();check(s.available,"snapshot unavailable");return {{"pending",s.pending},{"payloadBytes",s.payloadBytes},{"admitted",s.admitted},{"reaped",s.reaped},{"lastReapedOperation",s.lastReapedOperation},{"lastReapedLease",s.lastReapedLease},{"lastReapedError",s.lastReapedError},{"sealed",s.sealed},{"closeFailures",s.closeFailures}};}
struct Pair {
 std::wstring name;HANDLE server=nullptr,client=INVALID_HANDLE_VALUE;transport::Runtime* owner=new transport::Runtime();
 explicit Pair(std::wstring requested=L""){
  name=requested.empty()?L"\\\\.\\pipe\\YMCC-R44-prod-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64())+L"-"+std::to_wstring(++pairs):std::move(requested);
  server=CreateNamedPipeW(name.c_str(),PIPE_ACCESS_DUPLEX|FILE_FLAG_OVERLAPPED|FILE_FLAG_FIRST_PIPE_INSTANCE,PIPE_TYPE_MESSAGE|PIPE_READMODE_MESSAGE|PIPE_WAIT|PIPE_REJECT_REMOTE_CLIENTS,1,16384,16384,0,nullptr);check(server!=INVALID_HANDLE_VALUE,"create private server");DWORD e=99;check(owner->adopt(server,name,e)&&e==0,"owner adopt");
 }
 void connect(){client=CreateFileW(name.c_str(),GENERIC_READ|GENERIC_WRITE,0,nullptr,OPEN_EXISTING,FILE_FLAG_OVERLAPPED,nullptr);check(client!=INVALID_HANDLE_VALUE,"open private peer");DWORD mode=PIPE_READMODE_MESSAGE;check(SetNamedPipeHandleState(client,&mode,nullptr,nullptr)!=FALSE,"message mode");ULONG pid=0;check(GetNamedPipeClientProcessId(server,&pid)!=FALSE&&pid==GetCurrentProcessId(),"client PID");pid=0;check(GetNamedPipeServerProcessId(client,&pid)!=FALSE&&pid==GetCurrentProcessId(),"server PID");auto r=owner->run(server,transport::Kind::Connect,nullptr,0,1000);check(r.ok&&r.initialError==ERROR_PIPE_CONNECTED&&!r.byteCountKnown,"connect normalization");}
 ~Pair(){owner->close(server);owner->sealAndReap();if(client!=INVALID_HANDLE_VALUE)CloseHandle(client);}
};
// Peer operations keep their stack OVERLAPPED alive until a trusted result;
// tests throw on timeouts only after cancelling and verifying terminal state.
static DWORD peerIo(HANDLE h,bool write,void* data,DWORD size){HANDLE event=CreateEventW(nullptr,TRUE,FALSE,nullptr);check(event!=nullptr,"peer event");OVERLAPPED ov{};ov.hEvent=event;DWORD n=0;BOOL ok=write?WriteFile(h,data,size,nullptr,&ov):ReadFile(h,data,size,nullptr,&ov);DWORD e=ok?0:GetLastError();if(!ok&&e==ERROR_IO_PENDING){DWORD w=WaitForSingleObject(event,2000);if(w!=WAIT_OBJECT_0){CancelIoEx(h,&ov);check(WaitForSingleObject(event,2000)==WAIT_OBJECT_0,"peer cancel completion");}ok=GetOverlappedResult(h,&ov,&n,FALSE);e=ok?0:GetLastError();}else if(ok){ok=GetOverlappedResult(h,&ov,&n,FALSE);e=ok?0:GetLastError();}CloseHandle(event);check(ok&&e==0,"peer transfer");return n;}
static void normalAndPartial(){Pair p;p.connect();std::vector<unsigned char> request(64,0x45),read(64,0xA7);check(peerIo(p.client,true,request.data(),64)==64,"peer setup");auto r=p.owner->run(p.server,transport::Kind::Read,read.data(),64,1000);check(r.ok&&r.transferred==64&&read==request,"normal owned read");auto wrote=p.owner->run(p.server,transport::Kind::Write,request.data(),64,1000);check(wrote.ok,"normal owned write");check(peerIo(p.client,false,read.data(),64)==64&&read==request,"normal peer read");std::vector<unsigned char> bigger(128,0x5C);check(peerIo(p.client,true,bigger.data(),128)==128,"partial setup");auto partial=p.owner->run(p.server,transport::Kind::Read,read.data(),64,1000);check(!partial.ok&&partial.error==ERROR_MORE_DATA&&partial.byteCountKnown&&partial.transferred==64&&read==std::vector<unsigned char>(64,0x5C),"partial read");auto tail=p.owner->run(p.server,transport::Kind::Read,read.data(),64,1000);check(tail.ok&&tail.transferred==64,"partial tail");check(!p.owner->hasPending(),"normal owner retained");cases.push_back({{"case","production-header-normal-partial"},{"read",result(r)},{"write",result(wrote)},{"partial",result(partial)},{"snapshot",snapshot(*p.owner)}});}
static void timeoutAndSeal(){Pair p;p.connect();std::vector<unsigned char> read(64,0xA7);auto r=p.owner->run(p.server,transport::Kind::Read,read.data(),64,0);check(!r.ok&&r.error==WAIT_TIMEOUT&&read==std::vector<unsigned char>(64,0xA7),"read timeout changed outcome/caller");p.owner->close(p.server);const auto end=GetTickCount64()+2000;while(p.owner->hasPending()&&GetTickCount64()<end){p.owner->maintenance();if(p.owner->hasPending())Sleep(1);}check(!p.owner->hasPending(),"cancel/close not reaped");DWORD e=99;check(p.owner->canCreate(p.name,e)&&e==0,"same-name gate not released");p.owner->sealAndReap();check(!p.owner->canCreate(p.name,e)&&e==ERROR_SHUTDOWN_IN_PROGRESS,"sealed create allowed");auto after=p.owner->run(p.server,transport::Kind::Read,read.data(),64,0);check(!after.ok&&after.error==ERROR_SHUTDOWN_IN_PROGRESS&&!after.admitted,"sealed issue allowed");cases.push_back({{"case","production-header-timeout-close-seal"},{"timeout",result(r)},{"afterSeal",result(after)},{"snapshot",snapshot(*p.owner)}});}
static void sameNameHandshake(){Pair p;p.connect();const auto name=p.name;std::vector<unsigned char> first(64,0xA7);auto failed=p.owner->run(p.server,transport::Kind::Read,first.data(),64,0);check(failed.error==WAIT_TIMEOUT,"same-name setup timeout");p.owner->close(p.server);CloseHandle(p.client);p.client=INVALID_HANDLE_VALUE;DWORD error=99;check(p.owner->canCreate(name,error),"same-name gate did not clear");HANDLE replacement=CreateNamedPipeW(name.c_str(),PIPE_ACCESS_DUPLEX|FILE_FLAG_OVERLAPPED,PIPE_TYPE_MESSAGE|PIPE_READMODE_MESSAGE|PIPE_WAIT|PIPE_REJECT_REMOTE_CLIENTS,1,16384,16384,0,nullptr);check(replacement!=INVALID_HANDLE_VALUE,"same-name actual recreate");check(p.owner->adopt(replacement,name,error),"same-name replacement adopt");p.server=replacement;p.connect();
 std::vector<unsigned char> wire={'H','E','L','L','O'},payload(64,0xA7);check(peerIo(p.client,true,wire.data(),static_cast<DWORD>(wire.size()))==wire.size(),"same-name HELLO write");auto hello=p.owner->run(replacement,transport::Kind::Read,payload.data(),64,1000);check(hello.ok&&hello.transferred==wire.size()&&std::equal(wire.begin(),wire.end(),payload.begin()),"same-name HELLO read");std::vector<unsigned char> ack={'O','K'};auto response=p.owner->run(replacement,transport::Kind::Write,ack.data(),2,1000);check(response.ok,"same-name ACK write");check(peerIo(p.client,false,payload.data(),64)==2&&payload[0]=='O'&&payload[1]=='K',"same-name ACK consume");check(hello.lease>failed.lease,"replacement reused stale lease");cases.push_back({{"case","production-header-same-name-new-connection-message-roundtrip"},{"protocolIsSyntheticNotRealHostHELLO",true},{"old",result(failed)},{"newRead",result(hello)},{"newWrite",result(response)},{"snapshot",snapshot(*p.owner)}});}
static void sealWhileBusy(){Pair p;p.connect();std::vector<unsigned char> read(64,0xA7);transport::Result response;std::atomic<bool> started{false};std::thread thread([&]{started.store(true,std::memory_order_release);response=p.owner->run(p.server,transport::Kind::Read,read.data(),64,250);});while(!started.load(std::memory_order_acquire))SwitchToThread();const auto deadline=GetTickCount64()+1000;while(!p.owner->hasPending()&&GetTickCount64()<deadline)Sleep(1);const bool observedPending=p.owner->hasPending();const auto begin=GetTickCount64();p.owner->sealAndReap();const auto elapsed=GetTickCount64()-begin;thread.join();p.owner->sealAndReap();check(observedPending,"fixture did not observe admitted operation before seal");check(elapsed<100,"seal blocked behind in-flight wait");check(!response.ok&&response.error==WAIT_TIMEOUT,"inflight timeout rewritten by seal");check(read==std::vector<unsigned char>(64,0xA7),"seal changed caller buffer");cases.push_back({{"case","production-header-seal-with-inflight-helper"},{"sealElapsedMs",elapsed},{"result",result(response)},{"snapshot",snapshot(*p.owner)}});}
#ifdef YMCC_PIPE_LATENCY_COST
#include "input_pipe_latency_cost_cases.inc"
#endif
int main(int argc,char**argv){try{
#ifdef YMCC_PIPE_LATENCY_COST
 const bool latencyMode=argc==2&&std::string(argv[1])=="--latency-cost";
#else
 const bool latencyMode=false;(void)argv;
#endif
 if(argc!=1&&!latencyMode)return 2;DWORD before=0,after=0;check(GetProcessHandleCount(GetCurrentProcess(),&before)!=FALSE,"initial handle count");normalAndPartial();timeoutAndSeal();sameNameHandshake();sealWhileBusy();
#ifdef YMCC_PIPE_LATENCY_COST
if(latencyMode)pipeLatencyCostCases();
#endif
check(GetProcessHandleCount(GetCurrentProcess(),&after)!=FALSE&&before==after,"private production-owner handle leak");std::cout<<json({{"pass",true},{"checks",checks},{"cases",cases},{"privatePipePairs",pairs},{"processHandlesBefore",before},{"processHandlesAfter",after},{"realProductOrInputDevicesUsed",false},{"runtimeObjectsIntentionallyProcessLifetime",true},{"noCPUOrCtrlCauseClaim",true}}).dump(2)<<'\n';return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
